begin;
create table trade_business.shipments(company_id uuid not null,id uuid not null,order_id uuid not null,no text not null,state text not null default 'draft' check(state in ('draft','submitted','confirmed','cancelled')),version integer not null default 1 check(version>0),day date not null,payload jsonb not null,total_minor numeric(38,0) not null default 0 check(total_minor>=0),confirmed_at timestamptz,created_by uuid not null,primary key(company_id,id),unique(company_id,order_id,id),unique(company_id,no),foreign key(company_id,order_id) references trade_business.orders(company_id,id));
create index shipments_order on trade_business.shipments(company_id,order_id,state,confirmed_at);
create table trade_business.shipment_lines(company_id uuid not null,id uuid not null,shipment_id uuid not null,order_id uuid not null,order_line_id uuid not null,quantity numeric(24,4) not null check(quantity>0),amount_minor numeric(38,0) not null default 0 check(amount_minor>=0),payload jsonb not null,primary key(company_id,id),unique(company_id,shipment_id,order_id,order_line_id,id),foreign key(company_id,order_id,shipment_id) references trade_business.shipments(company_id,order_id,id),foreign key(company_id,order_id,order_line_id) references trade_business.order_lines(company_id,order_id,id),check((payload->>'packages')::integer>0),check((payload->>'netKg')::numeric>0),check((payload->>'grossKg')::numeric>=(payload->>'netKg')::numeric));
create table trade_business.shipment_sources(company_id uuid not null,shipment_id uuid not null,shipment_line_id uuid not null,order_id uuid not null,order_line_id uuid not null,receipt_line_id uuid not null,quantity numeric(24,4) not null check(quantity>0),primary key(company_id,shipment_line_id,receipt_line_id),foreign key(company_id,shipment_id,order_id,order_line_id,shipment_line_id) references trade_business.shipment_lines(company_id,shipment_id,order_id,order_line_id,id),foreign key(company_id,order_id,order_line_id,receipt_line_id) references trade_business.receipt_lines(company_id,order_id,order_line_id,id));
create index shipment_sources_receipt on trade_business.shipment_sources(company_id,receipt_line_id);
grant select,insert on trade_business.shipments,trade_business.shipment_lines,trade_business.shipment_sources to business_backend;
grant update(state,version,total_minor,confirmed_at) on trade_business.shipments to business_backend;
grant update(amount_minor) on trade_business.shipment_lines to business_backend;
commit;
